  }): Promise<{
    actions: ActionEntry[];
    response?: string;
    intent: string;
    confidence: number;
  }> {
    return processUnifiedAgentMessage(
      {
        actions: this.actions,
        ctx: this.ctx,
        fallbackBrainModel: this.fallbackBrainModel,
        fallbackWriterModel: this.fallbackWriterModel,
        logger: this.logger,
        openai: this.openai,
        planLimits: this.planLimits,
        primaryBrainModel: this.primaryBrainModel,
        prisma: this.prisma,
        response: this.response,
        writerModel: this.writerModel,
        executeToolAction: this.executeToolAction.bind(this),
        ...(this.agentRuntime !== undefined ? { agentRuntime: this.agentRuntime } : {}),
        ...(this.abiBuilder !== undefined ? { abiBuilder: this.abiBuilder } : {}),
      },
      params,
    );
  }

  /**
   * Public API: execute a single named tool directly.
   */
  async executeTool(
    tool: string,
    args: ToolArgs,
    ctx: { workspaceId: string; contactId?: string; phone?: string },
  ): Promise<unknown> {
    return this.executeToolAction(
      ctx.workspaceId,
      ctx.contactId || '',
      ctx.phone || '',
      tool,
      args,
    );
  }

  /** Build quoted reply plan (delegates to response service). */
  async buildQuotedReplyPlan(params: {
    workspaceId: string;
    contactId?: string;
    phone: string;
    draftReply: string;
    customerMessages: Array<{ content: string; quotedMessageId: string }>;
  }): Promise<Array<{ quotedMessageId: string; text: string }>> {
    return this.response.buildQuotedReplyPlan(
      this.openai,
      this.writerModel,
      this.fallbackWriterModel,
      this.planLimits,
      params,
    );
  }

  // ───────── tool router ─────────

  private async executeToolAction(
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
    context?: UnknownRecord,
  ): Promise<unknown> {
    return executeUnifiedAgentToolAction(
      {
        actions: this.actions,
        auditService: this.auditService,
        fallbackBrainModel: this.fallbackBrainModel,
        logger: this.logger,
        openai: this.openai,
        primaryBrainModel: this.primaryBrainModel,
        prisma: this.prisma,
        ...(this.agentRuntime !== undefined ? { agentRuntime: this.agentRuntime } : {}),
        ...(this.riskGate !== undefined ? { riskGate: this.riskGate } : {}),
      },
      {
        workspaceId,
        contactId,
        phone,
        tool,
        args,
        ...(context !== undefined ? { context } : {}),
      },
    );
  }





